import React, { useState, useMemo } from "react";
import { FaInstagram, FaFacebookF, FaTwitter } from "react-icons/fa";
import products from "../products/Products";

import {
  Gem,
  Sparkles,
  CircleDot,
  Star,
  Link2,
  Watch,
  ShoppingBag,
} from "lucide-react";

import { Link } from "react-router-dom";

/* ============================================================
   FONTS
   ============================================================ */

const fontImport = `
  @import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400&family=Jost:wght@300;400;500;600&display=swap');
`;

/* ============================================================
   CATEGORY DATA
   ============================================================ */

const CATEGORIES = [
  { id: "All", label: "All", icon: Sparkles },
  { id: "Rings", label: "Rings", icon: Gem },
  { id: "Necklaces", label: "Necklaces", icon: Sparkles },
  { id: "Bracelets", label: "Bracelets", icon: CircleDot },
  { id: "Earrings", label: "Earrings", icon: Star },
  { id: "Chains", label: "Chains", icon: Link2 },
  { id: "Watches", label: "Watches", icon: Watch },
];

const CATEGORY_ICON = {
  Rings: Gem,
  Necklaces: Sparkles,
  Bracelets: CircleDot,
  Earrings: Star,
  Chains: Link2,
  Watches: Watch,
};

/* ============================================================
   PRODUCTS
   ============================================================ */

const PRODUCTS = products.map((p) => ({
  id: p.id,
  name: p.title,
  category: p.category,
  price: Number(p.price) || 0,
  icon: CATEGORY_ICON[p.category] || Sparkles,
  badge: p.badge,
  image: p.thumbnail,
}));

/* ============================================================
   FOOTER
   ============================================================ */

function PlaceholderFooter() {
  return (
    <footer className="lux-footer">
      <div className="lux-footer-inner">

        <div className="lux-footer-col lux-footer-brand">

          <div className="lux-logo lux-logo-footer">
            MAISON&nbsp;&amp;&nbsp;LUXE
          </div>

          <p>
            Fine accessories, crafted with intention.
            Timeless pieces for every story.
          </p>

          <div className="lux-footer-social">

            <a href="#" aria-label="Instagram">
              <FaInstagram size={16} />
            </a>

            <a href="#" aria-label="Facebook">
              <FaFacebookF size={16} />
            </a>

            <a href="#" aria-label="Twitter">
              <FaTwitter size={16} />
            </a>

          </div>

        </div>

        <div className="lux-footer-col">

          <h4>Shop</h4>

          <a href="#">Rings</a>
          <a href="#">Necklaces</a>
          <a href="#">Watches</a>

        </div>

        <div className="lux-footer-col">

          <h4>Support</h4>

          <a href="#">Shipping</a>
          <a href="#">Returns</a>
          <a href="#">Contact Us</a>

        </div>

        <div className="lux-footer-col">

          <h4>Newsletter</h4>

          <p>
            Be first to know about new arrivals.
          </p>

          <div className="lux-footer-form">

            <input
              type="email"
              placeholder="Your email"
            />

            <button type="button">
              Join
            </button>

          </div>

        </div>

      </div>

      <div className="lux-footer-bottom">

        © {new Date().getFullYear()} Maison &amp; Luxe.
        All rights reserved.

      </div>

    </footer>
  );
}


/* ============================================================
   ALL CART
   ============================================================ */

function AllCart() {

  const [selectedCategory, setSelectedCategory] =
    useState("All");

  const filteredProducts = useMemo(() => {

    if (selectedCategory === "All") {
      return PRODUCTS;
    }

    return PRODUCTS.filter(
      (product) =>
        product.category === selectedCategory
    );

  }, [selectedCategory]);

  return (
    <>
      <style>
        {fontImport}
      </style>

      <main className="lux-page">

        {/* ====================================================
            HERO
        ==================================================== */}

        <section className="lux-collections-hero">

          <div className="lux-collections-hero-content">

            <span className="lux-hero-eyebrow">
              MAISON &amp; LUXE
            </span>

            <h1>
              All Products
            </h1>

            <p>
              Discover timeless pieces crafted to
              complement every moment and every story.
            </p>

          </div>

        </section>

        {/* ====================================================
            CATEGORIES
        ==================================================== */}

        <section className="lux-category-section">

          <div className="lux-category-list">

            {CATEGORIES.map((category) => {

              const Icon = category.icon;

              const isActive =
                selectedCategory === category.id;

              return (
                <button
                  key={category.id}
                  type="button"
                  className={
                    isActive
                      ? "lux-category-btn active"
                      : "lux-category-btn"
                  }
                  onClick={() =>
                    setSelectedCategory(
                      category.id
                    )
                  }
                >

                  <Icon
                    size={18}
                    strokeWidth={1.4}
                  />

                  <span>
                    {category.label}
                  </span>

                </button>
              );

            })}

          </div>

        </section>

        {/* ====================================================
            PRODUCTS
        ==================================================== */}

        <section className="lux-products-section">

          <div className="lux-products-header">

            <div>

              <span className="lux-products-eyebrow">
                COLLECTION
              </span>

              <h2>
                {selectedCategory === "All"
                  ? "All Pieces"
                  : selectedCategory}
              </h2>

            </div>

            <span className="lux-products-count">

              {filteredProducts.length}{" "}

              {filteredProducts.length === 1
                ? "piece"
                : "pieces"}

            </span>

          </div>

          {filteredProducts.length > 0 ? (

            <div className="lux-products-grid">

              {filteredProducts.map((product) => (

                <ProductCard
                  key={product.id}
                  product={product}
                />

              ))}

            </div>

          ) : (

            <div className="lux-empty-products">

              <Sparkles
                size={42}
                strokeWidth={1}
              />

              <h3>
                No products found
              </h3>

              <p>
                There are currently no products
                in this collection.
              </p>

              <button
                type="button"
                className="lux-btn lux-btn-solid"
                onClick={() =>
                  setSelectedCategory("All")
                }
              >
                View All Products
              </button>

            </div>

          )}

        </section>

        {/* ====================================================
            FOOTER
        ==================================================== */}

        <PlaceholderFooter />

      </main>
    </>
  );
}

/* ============================================================
   EXPORT
   ============================================================ */

export default AllCart;
